import SwiftUI
import AppKit
@main struct BlueprintCreatorApp:App{@NSApplicationDelegateAdaptor(AppDelegate.self)var delegate;@StateObject var m=AppModel();var body:some Scene{WindowGroup{ContentView().environmentObject(m).frame(minWidth:1040,minHeight:680)}.commands{CommandGroup(replacing:.appInfo){Button("About Blueprint Conversion Utility"){m.showAbout=true}};CommandGroup(replacing:.appSettings){Button("Connections..."){m.showConnections=true}.keyboardShortcut(",")};CommandGroup(replacing:.help){Button("Knowledge Base"){m.showKB=true};Button("Profile Inspector"){m.showProfileInspector=true}.disabled(m.selectedProfile == nil);Button("Explain & Recommend"){m.showAdvisor=true}.disabled(m.selectedProfile == nil);Button("Apple Schema Browser"){m.showAppleSchema=true};Divider();Button("Check for Updates..."){Task{await m.checkForAppUpdates(manual:true)}};Button("Blueprint Conversion Utility on GitHub"){NSWorkspace.shared.open(AppUpdateService.repositoryURL)}};CommandGroup(replacing:.newItem){EmptyView()};CommandMenu("Blueprint"){Button("Refresh Workspace"){Task{await m.load()}}.keyboardShortcut("r")}}}}
